public static void triggerCreditManagement(SalesTable _salesTable)
{
    SalesParmTable salesParmTable;
    SalesFormLetterContract salesFOrmLetterContatract = SalesFormLetterContract::construct(DocumentStatus::Confirmation);
    salesFOrmLetterContatract.parmSalesTable(_salesTable);
   // salesFOrmLetterContatract.parm

    FormletterJournalCreate journalCreate =  FormletterJournalCreate::newSalesJournalCreate(salesFOrmLetterContatract, salesParmTable);
    journalCreate.calcSalesTotal(_salesTable);
   // journalCreate.checkNoThrow();

    if (!journalCreate.METcredManCreditControlCheck())
    {
        journalCreate.METcredManCreditControlCreate();

    }
}

public void calcSalesTotal(SalesTable salestable)
{
    salesTotals =  SalesTotals::construct(salesTable);

}

private boolean METcredManCreditControlCheck()
{
    if (CredManParameters::find().SkipCreditCheckWhenCancelingPackingSlip && interCompanyFormletterContract && interCompanyFormletterContract.parmVersioningUpdateType() == VersioningUpdateType::Cancel)
    {
        return true;
    }

    METCredManSalesFormletterProvider localFormLetterProvider = formletterProvider as METCredManSalesFormletterProvider;

    return localFormLetterProvider == null || (localFormLetterProvider != null && localFormLetterProvider.CredMancreditControlCheck());
}

private void METcredManCreditControlCreate()
{
    METCredManSalesFormletterProvider localFormLetterProvider = formletterProvider as METCredManSalesFormletterProvider;

    localFormletterProvider.CredMancreditControlCreate();
}

public static void SOProformaPosting(SalesTable salesTable)
{
    SalesFormLetter salesFormLetter;
   // salesTable salesTable;
    //salesTable = SalesTable::find('SO-123');
    salesFormLetter = SalesFormLetter::construct(
        DocumentStatus::Confirmation);
                salesFormLetter.update(
        salesTable,
        systemDateGet(),
        SalesUpdate::All,
        AccountOrder::None,
        NoYes::Yes,
        NoYes::No,
        NoYes::No
        );
}
